use super::*;
#[test]fn field_birth_retains_actual_marker_and_owner(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🏗️birth/🔣️.json")).unwrap();assert!(fixture["cases"].as_array().unwrap().iter().any(|c|c["phase"]=="authored"&&c["attempt"]==false));let d=field_birth::<u64>();let work=field_birth_work::<u64>().unwrap();let grant=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:d.copy_bytes,maximum_capacity_bytes:d.capacity_bytes,maximum_release_bytes:d.capacity_bytes,maximum_depth:d.depth};let mut output=None;let mut actual=Some(37);let refused=admit_field_birth::<u64>(&mut output,grant,work,work-1,&mut actual);assert!(refused.result.is_err());assert_eq!(refused.work,0);assert_eq!(actual,Some(37));assert!(output.is_none());let denied=admit_field_birth::<u64>(&mut output,RetainedCloneGrant{maximum_items:0,..grant},work,work,&mut actual);assert_eq!(denied.work,0);assert_eq!(actual,Some(37));assert!(output.is_none());let denied=admit_field_birth::<u64>(&mut output,grant,work-1,work,&mut actual);assert_eq!(denied.work,0);assert_eq!(actual,Some(37));assert!(output.is_none());let occupied=admit_field_birth::<u64>(&mut output,grant,work,work,&mut actual);assert!(occupied.result.is_err());assert_eq!(occupied.work,0);assert_eq!(actual,Some(37));assert!(output.is_none());actual=None;let(turn,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||admit_field_birth::<u64>(&mut output,grant,work,work,&mut actual));assert_eq!(turn.work,work);let progress=turn.result.unwrap().progress();assert_eq!(actual,Some(d.capacity_bytes));assert_eq!(heap.requested_bytes,progress.retained_capacity_bytes);let mut owner=output.take().unwrap();owner.begin_close();assert!(owner.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!(heap.released_bytes,d.capacity_bytes);}
